int[] aktywne = {0}; int[] maxAktywne = {0};
Object licznikLock = new Object();
Object[] zasoby = {new Object(), new Object()};
Thread[] t = new Thread[4];
for (int i=0;i<4;i++) { final int idx = i % 2; t[i] = new Thread(() -> {
    synchronized (zasoby[idx]) {
        synchronized (licznikLock) { aktywne[0]++; maxAktywne[0] = Math.max(maxAktywne[0], aktywne[0]); }
        try { Thread.sleep(20); } catch (Exception e) {}
        synchronized (licznikLock) { aktywne[0]--; }
    }
}); }
for (Thread th : t) th.start();
for (Thread th : t) th.join(5_000);
System.out.println(maxAktywne[0] <= 2);

