Map<String,Object> blokady = new HashMap<>();
for (String nazwa : List.of("A","B","C")) blokady.put(nazwa, new Object());
void acquireBoth(String nazwaA, String nazwaB) {
    String pierwsza = nazwaA.compareTo(nazwaB) < 0 ? nazwaA : nazwaB;
    String druga = nazwaA.compareTo(nazwaB) < 0 ? nazwaB : nazwaA;
    synchronized (blokady.get(pierwsza)) { synchronized (blokady.get(druga)) { /* praca */ } }
}
// kilka watkow wywolujacych acquireBoth z roznymi parami, join(5_000), brak zawieszenia

